SELECT s.city, CASE WHEN s.sqft >= 13119 THEN 'high' WHEN s.sqft >= 3953 THEN 'mid' ELSE 'low' END AS sqft_bucket, SUM(CASE WHEN o.channel = 'store' THEN o.amount ELSE 0 END) AS store_amount, SUM(o.shipping_fee) AS total_shipping_fee FROM orders o LEFT JOIN stores s ON s.id = o.store_id GROUP BY s.city, CASE WHEN s.sqft >= 13119 THEN 'high' WHEN s.sqft >= 3953 THEN 'mid' ELSE 'low' END;
